#include "scheduler/engine.hpp"
namespace scheduler { std::vector<std::string> SchedulerEngine::run(std::vector<Worker>const& workers,std::function<void(Task const&)> handler){if(!handler)handler=[](Task const&){};std::vector<std::string> completed;while(true){DependencyGraph g(catalog_);StablePriorityQueue<std::string> ready;for(auto const&id:g.ready_ids()){auto&t=catalog_.get_mut(id);if(t.status==Status::pending)t=t.transitioned(Status::ready);ready.push(id,t.priority);}bool progressed=false;while(!ready.empty()){auto id=ready.pop();auto&t=catalog_.get_mut(id);auto worker=std::ranges::find_if(workers,[&](auto const&w){return w.can_run(t);});if(worker==workers.end())continue;progressed=true;t=t.transitioned(Status::running);try{handler(t);t=t.transitioned(Status::succeeded);}catch(...){t=t.transitioned(Status::failed);}completed.push_back(id);}if(!progressed)break;}return completed;} }
